function snd(a,v){if(VOL<=0)return;a.volume=Math.min(1,v*VOL);a.play().catch(()=>{})}

let AC;function ac(){return AC=AC||new (window.AudioContext||window.webkitAudioContext)()}
function tone(f,d,type,v,delay,slide){const A=ac(),t=A.currentTime+(delay||0),o=A.createOscillator(),g=A.createGain();o.type=type||'sine';o.frequency.setValueAtTime(f,t);if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+d);g.gain.setValueAtTime(v||.15,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g).connect(A.destination);o.start(t);o.stop(t+d)}
function noise(d,v){const A=ac(),b=A.createBuffer(1,A.sampleRate*d,A.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*(1-i/a.length);const n=A.createBufferSource(),g=A.createGain();n.buffer=b;g.gain.value=v;n.connect(g).connect(A.destination);n.start()}
const sRip=()=>{const a=new Audio('data:audio/mpeg;base64,');snd(a,1)},sFlip=()=>{const a=new Audio('data:audio/mpeg;base64,');snd(a,.7)},sEpic=()=>{const a=new Audio('data:audio/mpeg;base64,');snd(a,1)},sRare=()=>{const a=new Audio('data:audio/mpeg;base64,');snd(a,.8)},sLeg=()=>{const a=new Audio('data:audio/mpeg;base64,');snd(a,1)},sShake=()=>{const a=new Audio('data:audio/mpeg;base64,');snd(a,.8)};
async function open(){if(pk.classList.contains('shake')||pk.dataset.busy)return;if(!TOK)return login();if(ME&&!ME.bereit)return say('Heute schon geöffnet. Das nächste Pack gibt es um Mitternacht.');pk.dataset.busy=1;let r;
 try{r=await call('open','POST')}catch(e){delete pk.dataset.busy;return say('Keine Verbindung zum Server, bitte nochmal.')}
 if(!r||!r.ok){delete pk.dataset.busy;if(r&&r.sek)T=r.sek;return say(r&&r.msg||'Fehler beim Öffnen')}
 say('');ME=r;r.got.forEach(n=>got.add(n-0));T=r.sek;const w=r.karten.map(view),leg=w.some(x=>x.r==='leg');const D=ANIM?1:0;if(ANIM){pk.classList.add('shake');sShake()}if(leg){if(ANIM)setTimeout(()=>{pk.classList.add('gold');sEpic()},350);}
 setTimeout(()=>{pk.classList.add('gone');fx.classList.remove('on');void fx.offsetWidth;fx.classList.add('on');sRip();
  
  cs.innerHTML=w.map(x=>'<div class="c '+x.r+'" style="--r:'+R[x.r][1]+'"><div class="ci"><div class="bk"><div><i class="fr"></i><span class="bt">GAME BOOSTER</span><i class="ln a"></i><div class="em"><span><img src="'+PL+'" alt=""></span></div><i class="ln b"></i><span class="bb">LOBBY PACK · S1</span></div></div><div class="f"><div class="fi"><div class="art">'+(x.n?'<img src="img/packs/'+x.n+'.webp" alt="">':IMG[x.i==='clock'?'vpn':x.i]?'<img'+(x.r==='leg'&&x.i==='tag'?' class="own"':'')+' src="'+(x.r==='leg'&&x.i==='tag'?IMG.gold:IMG[x.i==='clock'?'vpn':x.i])+'" alt=""><span class="bdg">'+I[x.i]+'</span>':'<span class="big">'+I[x.i]+'</span>')+'</div>'+(x.code?'<div class="code" data-c="'+x.code+'" title="Kopieren">'+x.code+'</div>':'')+'<div class="val"><b>'+x.v+'</b><i>'+x.u+'</i></div><span class="s1">S1</span><div class="nm"><b>'+x.t+'</b></div><span class="rr">'+R[x.r][0]+'</span><div class="stt">'+x.st.map(q=>'<span><em>'+q[0]+'</em>'+q[1]+'</span>').join('')+'</div><div class="gl"></div></div></div></div></div>').join('');
  [...cs.children].forEach((c,i)=>{c.onmousemove=e=>{if(!ANIM||!c.classList.contains('open'))return;const r=c.getBoundingClientRect(),px=(e.clientX-r.left)/r.width,py=(e.clientY-r.top)/r.height;c.classList.add('tilt');c.querySelector('.ci').style.transform='rotateY('+(180-(px-.5)*22)+'deg) rotateX('+((py-.5)*-18)+'deg)';c.style.setProperty('--mx',(100-px*100)+'%');c.style.setProperty('--my',py*100+'%');c.style.setProperty('--ang',90+px*60)};c.onmouseleave=()=>{c.classList.remove('tilt');c.querySelector('.ci').style.transform=''};setTimeout(()=>c.classList.add('in'),D?150+i*160:0);setTimeout(()=>{c.classList.add('open');sFlip();if(w[i].r==='leg')setTimeout(sLeg,300);else if(w[i].r==='epic')setTimeout(sEpic,300);else if(w[i].r==='rare')setTimeout(sRare,300)},D?900+i*450:100+i*250);c.onclick=e=>{const k=e.target.closest('.code');if(k&&c.classList.contains('open'))return copy(k.dataset.c,k);c.classList.add('open')}});
  setTimeout(()=>pk.style.visibility='hidden',D?400:0);setTimeout(()=>{drawSet();show();if(r.set_code)say('Set komplett! Dein Monats-Code: '+r.set_code,1)},D?2400:900)},!ANIM?0:leg?1300:750)}
(function(){const z=[],n=18;for(let i=0;i<=n;i++)z.push((i/n*100).toFixed(2)+'% '+(i%2?'0':'6px'));const b=[],q=[];for(let i=n;i>=0;i--)b.push((i/n*100).toFixed(2)+'% calc(100% - '+(i%2?'0px':'6px')+')');document.querySelector('.pk').style.clipPath='polygon('+z.join(',')+','+b.join(',')+')'})();
pk.onclick=open;
const vol=document.getElementById('vol'),volv=document.getElementById('volv'),wv=document.getElementById('wv'),an=document.getElementById('anim');
let lastV=VOL||.8;
function showVol(){const p=Math.round(VOL*100);vol.value=p;volv.textContent=p;vol.style.setProperty('--v',p+'%');wv.style.display=p?'':'none';document.getElementById('mx').style.display=p?'none':''}
vol.oninput=()=>{VOL=vol.value/100;if(VOL)lastV=VOL;showVol();saveOpts()};
vol.onchange=()=>sFlip();
document.getElementById('mute').onclick=()=>{VOL=VOL?0:lastV;showVol();saveOpts()};
function showAnim(){an.classList.toggle('on',ANIM);document.body.classList.toggle('noanim',!ANIM)}
an.onclick=()=>{ANIM=!ANIM;showAnim();saveOpts()};
showVol();showAnim();
const gear=document.getElementById('gear'),pop=document.getElementById('pop');
gear.onclick=e=>{e.stopPropagation();const o=pop.classList.toggle('on');gear.setAttribute('aria-expanded',o)};
pop.onclick=e=>e.stopPropagation();
document.addEventListener('click',()=>{pop.classList.remove('on');gear.setAttribute('aria-expanded',false)});
