function say(t,ok){const m=document.getElementById('msg');m.textContent=t;m.style.color=ok?'#6ee7b7':'';m.hidden=!t}
function esc(t){return String(t).replace(/[&<>"']/g,c=>'&#'+c.charCodeAt(0)+';')}
async function call(p,m){const r=await fetch(API+p,{method:m||'GET',headers:{Authorization:'Bearer '+TOK}});if(r.status===401){TOK=null;ME=null;try{localStorage.removeItem('lpT')}catch(e){}show();return{ok:false,msg:'Bitte neu mit Discord anmelden'}}return r.json()}
